for(int j = 0; j <= 3; ++j)

draw((0,j)--(18,j));

draw((2*4,0)--(2*4,1));
draw((2*5,0)--(2*5,1));
draw((2*4,2)--(2*4,3));
draw((2*5,2)--(2*5,3));

label("$A$",(0,3),NW);
